CREATE OR REPLACE FUNCTION public.prepare_broadcast_send(p_guard uuid,p_actor uuid,p_payload text,p_audience text,p_campaign jsonb,p_recipients jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; g public.broadcast_send_guards; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' OR NOT public.has_role(p_actor,'admin'::public.app_role) THEN RAISE EXCEPTION 'forbidden'; END IF; IF jsonb_typeof(p_recipients)<>'array' OR jsonb_array_length(p_recipients)=0 OR jsonb_array_length(p_recipients)>20000 THEN RAISE EXCEPTION 'invalid recipients'; END IF; IF length(p_campaign->>'subject') NOT BETWEEN 1 AND 300 OR length(p_campaign->>'content_html') NOT BETWEEN 1 AND 200000 OR coalesce(p_campaign->>'sender_email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'invalid campaign'; END IF; bid:=public.claim_broadcast_send(p_guard,p_actor,p_payload,p_audience); IF EXISTS(SELECT 1 FROM public.broadcasts WHERE id=bid) THEN RETURN jsonb_build_object('id',bid,'duplicate',true); END IF; SELECT * INTO g FROM public.broadcast_send_guards WHERE id=p_guard; IF g.eligible_count<>jsonb_array_length(p_recipients) THEN RAISE EXCEPTION 'audience changed'; END IF; INSERT INTO public.broadcasts(id,subject,content_html,preheader,sender_email,sender_name,reply_to,segment_filters,status,total_recipients,created_by,promo_product_ids) VALUES(bid,p_campaign->>'subject',p_campaign->>'content_html',p_campaign->>'preheader',p_campaign->>'sender_email',p_campaign->>'sender_name',p_campaign->>'reply_to',coalesce(p_campaign->'segment_filters','{}'::jsonb),'sending',jsonb_array_length(p_recipients),p_actor,ARRAY(SELECT jsonb_array_elements_text(coalesce(p_campaign->'promo_product_ids','[]'::jsonb))::uuid)); INSERT INTO public.broadcast_recipients(broadcast_id,alumno_id,email,name,status) SELECT bid,CASE WHEN x->>'contact_type'='alumno' THEN (x->>'id')::uuid ELSE NULL END,lower(trim(x->>'email')),x->>'display_name','pending' FROM jsonb_array_elements(p_recipients) x; RETURN jsonb_build_object('id',bid,'duplicate',false); END $$; REVOKE ALL ON FUNCTION public.prepare_broadcast_send(uuid,uuid,text,text,jsonb,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.prepare_broadcast_send(uuid,uuid,text,text,jsonb,jsonb) TO service_role;